class InvalidPathError(ValueError):
    """The path is absolute or climbs above the virtual root."""


def normalize(path):
    if path.startswith('/'):
        raise InvalidPathError('Path must be relative')

    parts = []
    for part in path.split('/'):
        if part in ('', '.'):
            continue
        if part == '..':
            if not parts:
                raise InvalidPathError('Path climbs above the virtual root')
            parts.pop()
        else:
            parts.append(part)

    return '/'.join(parts) or '.'
```

The following tests assume `normalize` and `InvalidPathError` are defined as in the implementation. The reference repeatedly removes adjacent component/`..` pairs instead of using a stack.

```python
import itertools
import unittest


def reference(path):
    if path.startswith('/'):
        raise InvalidPathError('absolute path')
    tokens = [t for t in path.split('/') if t not in ('', '.')]
    while True:
        for i in range(len(tokens) - 1):
            if tokens[i] != '..' and tokens[i + 1] == '..':
                del tokens[i:i + 2]
                break
        else:
            break
    if '..' in tokens:
        raise InvalidPathError('above root')
    return '/'.join(tokens) or '.'


class TestNormalize(unittest.TestCase):
    def test_examples(self):
        for path, expected in [('', '.'), ('a//./B', 'a/B'),
                               ('a/../b', 'b'), ('a/..', '.')]:
            with self.subTest(path=path):
                self.assertEqual(normalize(path), expected)
        for path in ('/a', '/', '../a', 'a/../../b'):
            with self.subTest(path=path):
                with self.assertRaises(InvalidPathError):
                    normalize(path)

    def test_small_exhaustive_model(self):
        alphabet = ('', '.', '..', 'a', 'B')
        for length in range(5):
            for tokens in itertools.product(alphabet, repeat=length):
                path = '/'.join(tokens)
                with self.subTest(path=path):
                    try:
                        expected = reference(path)
                    except InvalidPathError:
                        with self.assertRaises(InvalidPathError):
                            normalize(path)
                    else:
                        actual = normalize(path)
                        self.assertEqual(actual, expected)
                        self.assertEqual(normalize(actual), actual)

if __name__ == '__main__':
    unittest.main()
```

The model checks accepted outputs, rejection and idempotence over a bounded input space; examples check specific contract boundaries. These tests cannot prove correctness for arbitrary-length paths or every possible token, and the reference itself could contain an error.

Treat the base as a path from the virtual root to a directory. Validate and normalize it independently with `normalize`; reject it if it begins with `/` or climbs above the root, even if the child could otherwise cancel that traversal.

The child is relative to that base. Reject a child beginning with `/`, then normalize the base and child together. A child’s `..` may remove base components, but any attempt to climb above the virtual root is rejected immediately.

```python
def resolve(base, child):
    normalized_base = normalize(base)
    if child.startswith('/'):
        raise InvalidPathError('Child path must be relative')
    return normalize(normalized_base + '/' + child)
```

For example, `resolve('A/b', '../c')` returns `A/c`; `resolve('A', '../../c')` raises `InvalidPathError`. An empty base or child is allowed, and an empty combined result is `.`.

