import unittest


def check_properties(test, cells):
    result = runs(cells)
    expanded = set()
    for y, start, end in result:
        test.assertLess(start, end)
        for x in range(start, end):
            test.assertNotIn((x, y), expanded)
            expanded.add((x, y))
    test.assertEqual(expanded, set(cells))
    test.assertEqual(result, sorted(result, key=lambda r: (r[0], r[1])))
    for previous, current in zip(result, result[1:]):
        if previous[0] == current[0]:
            # Adjacent intervals must have at least one absent cell between them.
            test.assertLess(previous[2], current[1])


class TestRuns(unittest.TestCase):
    def test_example_and_duplicates(self):
        cells = [(-2, 0), (-1, 0), (1, 0), (2, 0),
                 (0, 1), (2, 1), (-2, 0)]
        self.assertEqual(runs(cells), [
            (0, -2, 0), (0, 1, 3), (1, 0, 1), (1, 2, 3)
        ])
        check_properties(self, cells)

    def test_isolated_and_negative_rows(self):
        cells = [(3, -2), (-4, -2), (0, 5)]
        self.assertEqual(runs(cells), [(-2, -4, -3), (-2, 3, 4), (5, 0, 1)])
        check_properties(self, cells)

    def test_empty(self):
        self.assertEqual(runs([]), [])
        check_properties(self, [])

if __name__ == '__main__':
    unittest.main()
